{
  "cost": {
    "notion": {
      "base": "it is literally free for personal use. unlimited pages and blocks, and if your files are common weight, you can stay free. the api is rate-limited, but that probably does not matter to a solo researcher.",
      "extras": "there are no needful extras. the built-in sync is included, and version history too."
    },
    "obsidian": {
      "base": "the app itself is free for personal use. core features like markdown, links, and graph view are free.",
      "extras": "sync options can add costs. use my own dropbox (file source and conflict risks), or pay for obsidian sync or other cloud services. if you're using dropbox, the storage plan has a cost (even if you already pay), and cloud-synced vaults can be slow down backup speed or trigger duplicate files."
    }
  },
  "offline&connectivity_due_to_spotty_wifi": {
    "notion": {
      "offline": "you can edit cached pages offline, and changes are stored and synced when the network comes back. but creating new pages or dealing with big attachments directly depends on network. if the wifi disappears for an entire day, some features are partially usable but not all. reliability comes from the cloud."
    },
    "obsidian": {
      "offline": "the vault is local file on your drive, so every edit works instantly and offline. no dependence on a network for editing. so under café spotty wifi, obsidian is undoubtedly reliable."
    },
    "summary": ["offline edit reliability: obsidian lens 100% reliable; notion lens reliable on cached content, but 'offline' experience is not intended."
    ]
  },
  "sync_multi_device": {
    "notion": {
      "sync": "built-in cloud sync. edit on laptop, pick up on phone and changes are there. cross-platform (web, ios, android, desktop) and version history is built-in and consistent."
    },
    "obsidian": {
      "sync": "has to rely on third-party sync (dropbox, icloud, syncthing, or paid obsidian sync). dropbox sets conflict (duplicate files, versioning) and the entire vault is stored in one folder under the service, which can be heavy. obsidian sync is a paid feature ($4–$8/month) if user forgets."
    },
    "summary": "notion integration is seamless and free; obsidian needs workaround (extra cost or quirks). if you often switch devices and want zero-setup, notion $ is clearly more convenient."
  },
  "portability_long_term_data_control": {
    "notion": {
      "data_format": "data is not stored only in notion cloud. export is possible as markdown or csv, but the exported markdown does not preserve database structure, relations, roll-ups, or embedded content well. you would lose the convenience of notion's databases and template linkages."
    },
    "obsidian": {
      "data_format": "the vault is plain text markdown files with standard internal links using [[double brackets]]. you can open these files with any text editor, sync with any cloud service, convert to markdown-based tools, or just archive them. long-term risk is near zero, no proprietary lock-in."
    },
    "summary": "obsidian is much more portable and long-term safe due to plain text files. notion is easy now but trap if you ever want to move or if the service changes."
  },
  "features_fit_for_research": {
    "notion": {
      "databases_and_templates": "great for structured data: tables, kanban, relation between notes, templates for 'paper review', etc. if you track sources with multiple attributes (year, type, relevance), notion's database is a killer feature. also useful for creating a 'library' with filters and sorts."
    },
    "obsidian": {
      "linking_and_plugins": "internal linking, backlinks, and graph view are top tools for exploring how ideas connect. plugins (dataview for query, kanban, obsidian-tasks) customize workflows. but data organization is manual or plugin-dependent, not as immediately structured as notion."
    },
    "summary": "notion is better for structured, database-like research organization (source list, task tracking). obsidian is better for non-linear note-linking and idea mapping. which matters depends on whether you plan to manage things as a database or as a web of linked markdown."
  },
  "performance": {
    "notion": {
      "speed": "some users report lag on large workspaces with many embedded pages or database columns. the web app can be slow; the desktop app is a little better but not native. if you have a lot of research (hundreds of notes, attachments), performance may degrade."
    },
    "obsidian": {
      "speed": "local first, so the app is snap, even with a huge vault. no network-blocking operations. if you have a huge reading list, obsidian handles it with no issue."
    }
  },
  "workflow_style": {
    "notion": "good if you like a single, organized space with ready-to-use templates. less flexible for tinkering with raw files but good for ease of use and polish."
    ,
    "obsidian": "good if you value control, want to tinker, and are comfortable with a folder full of markdown files. more flexibility, but also more setup and maintenance (e.g. plugin choices, sync method)."
  },
  "long_term_risk_service_discontinuation_change": {
    "notion": "if notion shuts down or changes pricing, your data can be exported but it is not as straightforward. markdown export exists, but you lose interactivity and structured fields. as a sole proprietor, you are dependent on one cloud service for your work."
    ,
    "obsidian": "no dependence on the company. even if obsidian ceases to exist, your files are still in local files and can be opened anywhere."
  },
  "security_privacy": {
    "notion": "your data is on notion servers. for solo research it is usually fine, but if you are concerned about third-party access or what happens to your data if the service is acquired, this is a consideration."
    ,
    "obsidian": "your data is on your device. when you use dropbox sync, it is on dropbox servers (encrypted in transit and at rest). obsidian sync is end-to-end encrypted. either way, you control the local copy."
  },
  "competition_summary": {
    "brief": "for this particular use case (solo research, 3 months, spotty wifi, need portability) the rough recommendation is: obsidian is the practical choice for offline reliability, local control, plain-text notes, and long-term safety. notion is the practical choice if you want seamless multi-device sync, structured databases, and ease-of-use over long-term portability. depending on which matters more (project simplicity vs. control), either works, but if you are worried about loss of data or moving it later, obsidian is better."
  }
}
